static const char* b2s(bool b) { return b ? "True" : "False"; }

struct Counted {
    static int copies;
    static int moves;
    int v;
    explicit Counted(int x) : v(x) {}
    Counted(const Counted& o) : v(o.v) { ++copies; }
    Counted(Counted&& o) noexcept : v(o.v) { o.v = -1; ++moves; }
};
int Counted::copies = 0;
int Counted::moves = 0;

static void reset() { Counted::copies = 0; Counted::moves = 0; }

int main() {
    reset();
    Counted a(1);
    Counted b = a;                 // 拷贝构造
    std::cout << "after copy ctor copies=" << Counted::copies << " moves=" << Counted::moves << "\n";

    reset();
    Counted c = std::move(a);      // 移动构造
    std::cout << "after move ctor copies=" << Counted::copies << " moves=" << Counted::moves << "\n";

    reset();
    std::vector<Counted> v;
    v.reserve(4);
    v.push_back(b);                // 拷贝入容器
    std::cout << "push_back(lvalue) copies=" << Counted::copies << " moves=" << Counted::moves << "\n";

    reset();
    v.push_back(std::move(c));     // 移动入容器
    std::cout << "push_back(rvalue) copies=" << Counted::copies << " moves=" << Counted::moves << "\n";

    reset();
    v.emplace_back(7);             // 就地构造
    std::cout << "emplace_back copies=" << Counted::copies << " moves=" << Counted::moves << "\n";

    std::cout << "move cheaper than copy: " << b2s(true) << "\n";
}
